+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import ai.unifiedprocess.petclinic.core.ui.ApplicationErrorView;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.welcome.ui.WelcomeView;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.sidenav.SideNavItem;
+import com.vaadin.flow.data.provider.Query;
+import org.jooq.DSLContext;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import java.util.ArrayList;
+import java.util.List;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.*;
+import static org.junit.jupiter.api.Assertions.*;
+
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = {"BR-002", "BR-003"})
+    void menuOpensDirectoryWithNamesAndOrderedSpecialtiesAnonymously() {
+        navigate(WelcomeView.class);
+        SideNavItem link = assertDoesNotThrow(() -> find(SideNavItem.class)
+                .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Expected veterinarian navigation link");
+        UI.getCurrent().navigate(link.getPath());
+
+        var grid = test(grid());
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+        assertEquals(6, grid.size());
+        assertEquals("First Name", grid.getHeaderCell(0));
+        assertEquals("Last Name", grid.getHeaderCell(1));
+        assertEquals("Specialties", grid.getHeaderCell(2));
+        assertEquals("James", grid.getCellText(0, 0));
+        assertEquals("Carter", grid.getCellText(0, 1));
+        assertEquals("none", grid.getCellText(0, 2));
+        assertEquals("Linda", grid.getCellText(1, 0));
+        assertEquals("Douglas", grid.getCellText(1, 1));
+        assertEquals("dentistry, surgery", grid.getCellText(1, 2));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyDirectoryRendersGridWithoutRows() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+        navigate(VetsView.class);
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void callbacksFetchBoundedDistinctChunksThroughTheEnd() {
+        // Identical names exercise the ID tie-breaker across page boundaries.
+        for (int i = 0; i < 125; i++) {
+            dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME)
+                    .values("Pat", "Smith").execute();
+        }
+        navigate(VetsView.class);
+        var provider = grid().getDataProvider();
+        assertFalse(provider.isInMemory());
+        assertEquals(131, provider.size(new Query<>()));
+        List<Integer> ids = new ArrayList<>();
+        for (int offset = 0; offset < 131; offset += 20) {
+            List<Vet> page = provider.fetch(new Query<>(offset, 20, List.of(), null, null)).toList();
+            assertEquals(Math.min(20, 131 - offset), page.size());
+            ids.addAll(page.stream().map(Vet::id).toList());
+        }
+        assertEquals(131, ids.stream().distinct().count());
+        assertEquals(dsl.select(VETS.ID).from(VETS)
+                .orderBy(VETS.LAST_NAME, VETS.FIRST_NAME, VETS.ID).fetch(VETS.ID), ids);
+        assertTrue(provider.fetch(new Query<>(131, 20, List.of(), null, null)).toList().isEmpty());
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void fetchFailureReplacesDirectoryWithApplicationErrorView() {
+        navigate(VetsView.class);
+        var provider = grid().getDataProvider();
+        dsl.dropTable(VET_SPECIALTIES).execute();
+        provider.fetch(new Query<>(0, 20, List.of(), null, null)).toList();
+        assertErrorReplacesGrid();
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void countFailureReplacesDirectoryWithApplicationErrorView() {
+        navigate(VetsView.class);
+        var provider = grid().getDataProvider();
+        dsl.dropTable(VET_SPECIALTIES).execute();
+        dsl.dropTable(VETS).execute();
+        provider.size(new Query<>());
+        assertErrorReplacesGrid();
+    }
+
+    private void assertErrorReplacesGrid() {
+        assertDoesNotThrow(() -> find(ApplicationErrorView.class).single(),
+                "Data-access failures must show the application error view");
+        assertTrue(find(Grid.class).all().isEmpty(), "No vet grid may remain after a failure");
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Vet> grid() {
+        return assertDoesNotThrow(() -> find(Grid.class).single(), "Expected veterinarian grid");
+    }
+}
